using System.Linq;using UnityEngine;
public static class InspectExplorationLake {public static object Main(){var w=Object.FindAnyObjectByType<ExplorationWorld>();return new{lake=w.GetComponentsInChildren<WaterVolume>().Where(v=>v.ellipticalBounds).Select(v=>new{pos=v.transform.position.ToString(),renderer=v.GetComponentInChildren<Renderer>().bounds.ToString(),height=w.Map.Height(w.Map.LakeCentre),material=v.GetComponentInChildren<Renderer>().sharedMaterial.name}).ToArray(),mask=Shader.GetGlobalTexture("_ExplorationLoadedMask")==null?"null":Shader.GetGlobalTexture("_ExplorationLoadedMask").name};}}
